<?php
namespace Tests\Feature;
use App\Models\{Company,DueDiligenceCase,DueDiligenceItem,PropertyAcquisition,User}; use App\Services\PropertyAcquisitionService; use Illuminate\Foundation\Testing\RefreshDatabase; use Spatie\Permission\Models\Permission; use Tests\TestCase;
class DueDiligenceWorkflowTest extends TestCase { use RefreshDatabase; private function actor(Company $c,array $ps):User{$u=User::factory()->create(['company_id'=>$c->id,'role'=>'company_admin']);foreach($ps as $p){Permission::findOrCreate($p,'web');$u->givePermissionTo($p);}return $u;} public function test_required_pending_or_failed_items_block_clearance_and_authorized_waiver_allows_it():void{$c=Company::create(['name'=>'A','email'=>'a@test.com']);$u=$this->actor($c,['clear_due_diligence_case','waive_due_diligence_item']);$a=PropertyAcquisition::withoutGlobalScopes()->create(['company_id'=>$c->id,'type'=>'cash_purchase']);$case=DueDiligenceCase::withoutGlobalScopes()->create(['company_id'=>$c->id,'property_acquisition_id'=>$a->id,'opened_at'=>now()]);$item=DueDiligenceItem::withoutGlobalScopes()->create(['company_id'=>$c->id,'due_diligence_case_id'=>$case->id,'title'=>'Title deed','is_required'=>true]);$s=app(PropertyAcquisitionService::class);try{$s->clearCase($u,$case);$this->fail('Expected clearance block');}catch(\Illuminate\Validation\ValidationException){}$s->waiveItem($u,$item);$s->clearCase($u,$case->refresh());$this->assertSame('cleared',$case->refresh()->status);} }
